/*
 * TMM eBPF tutorial. Read docs/EBPF-TUTORIAL.md before loading.
 *
 * Build the default entry variant, or use -DTEMPLATE_EXIT=1 for exit.
 * Both use the same input and event formats. Use monitor mode first.
 * Field offsets must be resolved before verification and signing.
 */
#include "config_snapshot.bpf.h"

typedef unsigned char u8;
typedef ls_cfg_u32 u32;
typedef ls_cfg_u64 u64;

#ifndef TEMPLATE_EXIT
#define TEMPLATE_EXIT 0
#endif

/* 1. The host supplies 96 bytes. At exit, byte 40 holds the return value.
 * Argument pointers are addresses, not permission to dereference them.
 */
struct template_ctx {
    u64 arg[5];
    u64 result;
    u64 reserved[6];
};
_Static_assert(sizeof(struct template_ctx) == 96, "tracing context size");

/* 2. Helpers are host functions. These numbers are the program interface.
 * This runtime supports six general helpers; it is not kernel eBPF.
 */
static void *(*bpf_map_lookup_elem)(void *, const void *) = (void *)1;
static long (*bpf_map_update_elem)(void *, const void *, const void *, u64)
    = (void *)2;
static long (*bpf_map_delete_elem)(void *, const void *) = (void *)3;
#if !TEMPLATE_EXIT
static long (*bpf_probe_read)(void *, u32, const void *) = (void *)4;
#endif
static u64 (*bpf_ktime_get_ns)(void) = (void *)5;
static long (*bpf_perf_event_output)(void *, void *, u64, void *, u64)
    = (void *)25;

/* 3. Configuration: schema 1, exactly one 32-byte row, little-endian.
 * threshold: entry buffer length, or exit result, at which matched=1.
 * min_interval_ns: minimum time between successful event submissions.
 * reset_token: change this value to reset this thread's counter.
 * flags: bit 0 enables observation; bit 1 requests entry SAFE_RETURN.
 * reserved must be zero. Missing/invalid input continues normal TMM work.
 */
struct template_policy {
    u64 threshold;
    u64 min_interval_ns;
    u64 reset_token;
    u32 flags;
    u32 reserved;
};
#define ENABLED 1u
#define REQUEST_SAFE_RETURN 2u

/* 4. Mutable state is per thread, not shared across all TMM threads.
 * Do not use a pointer or this counter as an authenticated request ID.
 * The instance token prevents a reload from using old counter contents.
 */
struct template_state {
    u64 instance;
    u64 reset_token;
    u64 seen;
    u64 last_emit_ns;
};
struct ls_cfg_map_def tutorial_state __attribute__((section("maps"), used))
    = {1, 4, 32, 256, 0};
/* Use the full 256-entry shape. The current host's small-table hash
 * lookup can miss an inserted key. This program uses only key zero.
 */
struct ls_cfg_map_def tutorial_events __attribute__((section("maps"), used))
    = {4, 4, 4, 1, 0};
/* Keep map symbols global. The pinned verifier rejects local map symbols.
 * The configuration map is declared by config_snapshot.bpf.h.
 */

/* 5. Event ABI 1: fixed-width fields, no raw pointers or credentials.
 * The transport adds its own timestamp, sequence, slot and schema.
 * magic+abi identify THIS payload within the generic program schema.
 */
struct template_event {
    u32 magic, abi;
    u64 instance, revision, monotonic_ns, seen;
    u64 observed, threshold, result;
    u32 kind, flags, version, header_count;
    u32 matched, verdict;
};
_Static_assert(sizeof(struct template_policy) == 32, "configuration row");
_Static_assert(sizeof(struct template_state) == 32, "map value limit");
_Static_assert(sizeof(struct template_event) == 88, "event ABI");
#define NO_POLICY 1u
#define BAD_POLICY 2u
#define READ_FAILED 4u
#define MAP_FAILED 8u
#define CLOCK_FAILED 16u
#define DISABLED 32u
#define COUNTER_FULL 64u

#if !TEMPLATE_EXIT
/* 6. Minimal named-field views. Local offsets are placeholders.
 * CO-RE (Compile Once, Run Everywhere) supplies relocation records.
 * The build tools resolve them against the target build's type data.
 */
struct http_parser {
    u32 header_count;
} __attribute__((preserve_access_index));
struct http_parse_ctx {
    u8 version_num;
    struct http_parser *parser;
} __attribute__((preserve_access_index));
struct xbuf {
    u32 len;
} __attribute__((preserve_access_index));

static __attribute__((always_inline)) inline int
read_fields(struct template_ctx *ctx, struct template_event *event)
{
    struct http_parse_ctx *http = (void *)ctx->arg[0];
    struct xbuf *buffer = (void *)ctx->arg[1];
    struct http_parser *parser = 0;
    u8 version = 0;
    u32 length = 0;
    int valid = 0;

    if (!http || !buffer)
        goto out;
    if (bpf_probe_read(&version, sizeof version, &http->version_num))
        goto out;
    if (bpf_probe_read(&length, sizeof length, &buffer->len))
        goto out;
    /* Two-hop read: copy the pointer, check it, then copy its field. */
    if (bpf_probe_read(&parser, sizeof parser, &http->parser) || !parser)
        goto out;
    if (bpf_probe_read(&event->header_count, sizeof event->header_count,
                      &parser->header_count))
        goto out;
    event->version = version;
    event->observed = length;
    valid = 1;
out:
    return valid;
}
#define TEMPLATE_SECTION "fentry/http_parse_client_headers"
#else
/* At exit an argument's object might have been freed. Read only result. */
#define TEMPLATE_SECTION "fexit/http_parse_client_headers"
#endif

/* 7. One entry point per object. All helper errors have an explicit path.
 * The host owns actions: 0=FALLTHROUGH, 1=SAFE_RETURN at an entry hook.
 * SAFE_RETURN is a selection, not the error value returned to TMM's caller.
 */
__attribute__((section(TEMPLATE_SECTION), used))
u64 template(struct template_ctx *ctx)
{
    struct template_event event = {0};
    struct template_state fresh = {0};
    struct template_state *state = 0;
    struct ls_cfg_meta *meta = ls_cfg_get(0);
    struct template_policy *policy = 0;
    u32 key = 0;
    u64 interval = 0;

    event.magic = 0x544d4d31u;
    event.abi = 1;
    event.kind = TEMPLATE_EXIT ? 2 : 1;
    event.monotonic_ns = bpf_ktime_get_ns();
    if (!meta) {
        event.flags = NO_POLICY;
        goto emit;
    }
    event.instance = meta->instance;
    event.revision = meta->revision;
    if (meta->schema != 1 || meta->entries != 1) {
        event.flags = BAD_POLICY;
        goto emit;
    }
    policy = ls_cfg_get(1);
    if (!policy) {
        event.flags = NO_POLICY;
        goto emit;
    }
    if (policy->reserved || (policy->flags & ~3u)) {
        event.flags = BAD_POLICY;
        goto emit;
    }
    event.threshold = policy->threshold;
    interval = policy->min_interval_ns;
    state = bpf_map_lookup_elem(&tutorial_state, &key);
    if (!(policy->flags & ENABLED)) {
        event.flags = DISABLED;
        if (state && bpf_map_delete_elem(&tutorial_state, &key))
            event.flags |= MAP_FAILED;
        state = 0; /* A deleted value pointer must not be used. */
        goto emit;
    }
    if (!state || state->instance != meta->instance ||
        state->reset_token != policy->reset_token) {
        fresh.instance = meta->instance;
        fresh.reset_token = policy->reset_token;
        if (bpf_map_update_elem(&tutorial_state, &key, &fresh, 0)) {
            event.flags = MAP_FAILED;
            state = 0;
            goto emit;
        }
        state = bpf_map_lookup_elem(&tutorial_state, &key);
        if (!state) {
            event.flags = MAP_FAILED;
            goto emit;
        }
    }
    /* Saturate instead of wrapping a counter into an old value. */
    if (state->seen == ~0ull)
        event.flags |= COUNTER_FULL;
    else
        state->seen++;
    event.seen = state->seen;
#if TEMPLATE_EXIT
    event.result = ctx->result;
    event.observed = event.result;
    event.matched = event.observed >= policy->threshold;
#else
    if (!read_fields(ctx, &event)) {
        event.flags |= READ_FAILED;
        goto emit;
    }
    event.matched = event.observed >= policy->threshold;
    event.verdict = event.matched && (policy->flags & REQUEST_SAFE_RETURN);
#endif
    /* 8. Sampling affects output only, never the selected verdict.
     * The clock is monotonic. The transport timestamp is wall-clock time.
     */
    if (!event.monotonic_ns) {
        event.flags |= CLOCK_FAILED;
    } else if (state->last_emit_ns &&
               event.monotonic_ns >= state->last_emit_ns &&
               event.monotonic_ns - state->last_emit_ns < interval) {
        goto out;
    }
emit:
    /* 9. A full ring can refuse output. Keep the old successful time so
     * the next call can try again. Loss counters belong to the transport.
     * Missing/invalid input and read failures emit unsampled diagnostics.
     */
    if (!bpf_perf_event_output(ctx, &tutorial_events, 0,
                              &event, sizeof event) && state)
        state->last_emit_ns = event.monotonic_ns;
out:
    return event.verdict;
}

check_map_reuse.c.text:
/* Regression for output-map -> revoke -> hash-map storage reuse.
 * Exit 1 is the retained falsifier on the current host implementation.
 */
#define LS_MAP_GLUE_IMPL 1
#include "ls_map_glue.h"

int main(void)
{
    struct ls_map_def output = {4, 4, 4, 1, 0};
    struct ls_map_def counter = {1, 4, 32, 256, 0};
    uint32_t key = 0;
    uint64_t value[4] = {1, 2, 3, 4};
    uint64_t first = ls_map_reloc(0, (const uint8_t *)&output, sizeof output,
                                  "old_output", 0, sizeof output);
    struct ls_map_set *set = ls_map_current();
    if (!set || first != 0 || !set->m[0].is_ring)
        return 2;
    ls_map_reset_shapes();
    uint64_t next = ls_map_reloc(0, (const uint8_t *)&counter, sizeof counter,
                                 "new_counter", 0, sizeof counter);
    ls_map_reloc(0, (const uint8_t *)&output, sizeof output,
                 "new_output", 0, sizeof output);
    set = ls_map_current();
    struct ls_map *map = ls_map_get(set, next);
    if (!map)
        return 2;
    int result = ls_map_update(map, (const uint8_t *)&key, (const uint8_t *)value);
    printf("{\"index\":%llu,\"registered_type\":%u,\"storage_is_ring\":%u,"
           "\"update_result\":%d,\"passed\":%s}\n",
           (unsigned long long)next, g_ls_shapes[next].type, map->is_ring,
           result, result == 0 ? "true" : "false");
    return result == 0 ? 0 : 1;
}

check_output_result.c.text:
/* Use the real output bridge. Check its result against a consumed record and
 * an observed full-ring drop. Exit 1 retains the current reversed-result bug.
 */
#include "ls_tp_emit.c"

enum ls_verdict ls_vm_call(int slot, void *ctx, size_t len)
{
    (void)slot; (void)ctx; (void)len;
    abort(); /* This test must never enter the VM dispatch path. */
}

int main(void)
{
    g_tp_seg = calloc(1, LS_TP_SEG_SZ);
    if (!g_tp_seg)
        return 2;
    g_tp_seg_tried = 1;
    g_tp_seg->n_rings = 1;
    g_tp_seg->ring_stride = LS_TP_STRIDE;
    struct ls_ring *ring = ls_tp_seg_ring(g_tp_seg, 0);
    ls_ring_init(ring, LS_TP_RING_BYTES, LS_RING_STREAM);
    uint64_t payload = 42, received = 0;
    struct ls_rec header;
    int delivered = ls_tp_publish_raw(5, &payload, sizeof payload);
    int length = ls_ring_consume(ring, &header, &received, sizeof received);
    if (length != (int)sizeof payload || received != payload)
        return 2;
    int dropped = 99;
    for (unsigned i = 0; i < 2000 && !atomic_load(&ring->drops); i++)
        dropped = ls_tp_publish_raw(5, &payload, sizeof payload);
    int passed = delivered == 0 && dropped == -1 && atomic_load(&ring->drops) == 1;
    printf("{\"delivered_result\":%d,\"consumed_bytes\":%d,"
           "\"dropped_result\":%d,\"drops\":%llu,\"passed\":%s}\n",
           delivered, length, dropped, (unsigned long long)atomic_load(&ring->drops),
           passed ? "true" : "false");
    free(g_tp_seg);
    return passed ? 0 : 1;
}

ls_tp_emit.c.text:
/* ls_tp_emit.c --- the STDINC side of the tracepoint boundary.
 *
 * It exists as its own translation unit because the caller cannot reach ls_vm.h:
 * every file in modules/hudfilter/http compiles in TMM's -nostdinc world, and
 * ls_vm.h needs stdint/stddef. This file is marked STDINC in src/compile/filelist
 * and is the only place the two worlds meet for telemetry --- the same shape
 * ls_prep.c already uses for the bootstrap.
 *
 * TWO CONSUMERS, ONE RECORD. Every record reaching this function goes to:
 *
 *   1. the VM, which answers a question about it (counted in fired/safe_returns)
 *   2. the shared-memory ring, which carries the bytes themselves off-box
 *
 * They are independent. The VM answers "how many were malformed" with two
 * counters and no transport. The ring answers "show me that request", which
 * needs a drain agent and a segment. Neither is a substitute for the other, and
 * the ring is off unless LS_TP_RING names a path.
 *
 * WHY THE VERDICT IS DISCARDED HERE. ls_vm_call returns one, because the shield
 * path needs it. A tracepoint does not, and giving the call site no way to
 * receive it means no future edit there can accidentally start acting on it. The
 * cast to void is the entire safety property, and it is cheaper and more durable
 * than a mode check --- see ls_tp.h.
 */
#include "ls_tp.h"
#include "ls_tp_ring.h"
#include "ls_tp_shield.h"
#include "ls_vm.h"

#include <stdlib.h>
#include <time.h>

/* Segment handle, resolved once. NULL means "ring disabled", which is the
 * default and the shipped state: LS_TP_RING unset costs a load and a branch. */
static struct ls_tp_seg *g_tp_seg;
static int               g_tp_seg_tried;
/* Atomic, and the live run is why. Two TMM threads reach this call site --- the
 * segment showed claimed=2 --- so a plain ++ is a data race that silently hands
 * two records the same seq. It did not collide in an 18-record sample, which is
 * exactly how this class of bug survives testing. A consumer ordering or
 * de-duplicating by seq would be quietly wrong under load. */
static _Atomic unsigned long long g_tp_seq;

/*
 * Bring up the segment. Called from the tracepoint path rather than from init,
 * because INIT_LATE runs once per TMM thread and the map only needs to happen
 * once --- the guard below is simpler than a second election, and open/mmap on
 * the very first request is a one-time cost, not a per-record one.
 *
 * Every failure is silent and permanent for the process. Telemetry that keeps
 * retrying a failed mmap on the hot path is worse than telemetry that is off.
 */
static void
ls_tp_seg_bootstrap(void)
{
    const char *path;

    if (g_tp_seg_tried)
        return;
    g_tp_seg_tried = 1;

    path = getenv("LS_TP_RING");
    if (path == NULL || *path == '\0')
        return;

    g_tp_seg = ls_tp_seg_open(path, 1);
    fprintf(stderr, "ls_tp: ring %s %s (%u rings x %u bytes)\n", path,
            g_tp_seg ? "mapped" : "FAILED --- telemetry off, traffic unaffected",
            (unsigned)LS_TP_MAX_RINGS, (unsigned)LS_TP_RING_BYTES);
}

int
ls_tp_dispatch(int slot, const void *rec, unsigned long len, unsigned int hook_id)
{
    enum ls_verdict v;

    /*
     * ls_vm_call takes void*, not const void*, because a verified program may
     * legally write every byte of what it is handed: PREVAIL does not consume a
     * `writable: []` annotation, so it cannot express a read-only region
     * (finding O1). The cast is safe HERE for a reason specific to this path ---
     * `rec` points at the caller's own stack record, built fresh for this
     * invocation and dead when it returns. A program that scribbles on it
     * corrupts nothing but its own input.
     *
     * That is exactly why the record is a stack copy rather than a view onto
     * TMM state. Handing a program a pointer into hd->ci would turn a telemetry
     * mechanism into a way to modify the parsed request.
     */
    v = ls_vm_call(slot, (void *)(unsigned long)rec, (size_t)len);

    /*
     * Then the bytes. AFTER the VM, deliberately: the program may write to the
     * record, and what a consumer should see is what the program left, not a
     * pre-program copy that disagrees with the counters.
     */
    ls_tp_seg_bootstrap();
    if (g_tp_seg != NULL) {
        struct timespec ts;
        /* CLOCK_REALTIME resolves through the vDSO --- no syscall, tens of ns ---
         * and wall clock is what a feed needs to correlate with anything else.
         * CLOCK_REALTIME_COARSE is a few ns cheaper at ~4ms granularity, which
         * would be fine for rates and useless for latency; revisit if the
         * per-call budget ever demands it. Read only when the ring is on. */
        clock_gettime(CLOCK_REALTIME, &ts);
        (void)ls_tp_ring_publish(g_tp_seg, hook_id,
                                 ls_tp_schema_for(hook_id),
                                 (unsigned)slot,
                                 atomic_fetch_add_explicit(&g_tp_seq, 1,
                                                           memory_order_relaxed),
                                 (unsigned long long)ts.tv_sec * 1000000000ull
                                     + (unsigned long long)ts.tv_nsec,
                                 rec, (unsigned int)len);
    }
    return (int)v;
}

/*
 * PUBLISH ONLY --- no program run. This is what bpf_ringbuf_output() reaches.
 *
 * WHY IT CANNOT BE ls_tp_dispatch. That function runs the slot's program and THEN
 * publishes. Calling it from inside a helper invoked BY that program would re-enter the
 * VM from within itself: unbounded recursion on the data path, with each level consuming
 * a fresh uBPF stack frame. So the two halves are separated and the helper gets the half
 * that does not execute anything.
 *
 * SCHEMA IS THE PROGRAM'S, NOT OURS. The bytes are whatever the program chose, so the
 * host cannot claim to know their shape --- it publishes them under LS_TP_HOOK_PROG /
 * LS_TP_SCHEMA_PROG and the drain reports length and hex. Interpreting them is a contract
 * between the program's author and their own consumer, and pretending otherwise would put
 * a schema number on bytes nobody validated.
 *
 * Returns 0 on success, -1 when the ring is off or the record does not fit. -1 is
 * ordinary: the ring is disabled unless LS_TP_RING names a segment.
 */
int
ls_tp_publish_raw(int slot, const void *rec, unsigned long len)
{
    struct timespec ts;

    ls_tp_seg_bootstrap();
    if (g_tp_seg == NULL)
        return -1;

    clock_gettime(CLOCK_REALTIME, &ts);
    return ls_tp_ring_publish(g_tp_seg, LS_TP_HOOK_PROG, LS_TP_SCHEMA_PROG,
                              (unsigned)slot,
                              atomic_fetch_add_explicit(&g_tp_seq, 1,
                                                        memory_order_relaxed),
                              (unsigned long long)ts.tv_sec * 1000000000ull
                                  + (unsigned long long)ts.tv_nsec,
                              rec, (unsigned int)len) == 0 ? 0 : -1;
}

/*
 * Shield enforcement-evidence emit. See ls_tp.h for the contract.
 *
 * RATE-LIMITED, and the shape is deliberate: the first LS_TP_SHIELD_BURST events
 * always publish --- a first strike, or a demo, must be SEEN --- then 1 in
 * LS_TP_SHIELD_EVERY thereafter. A flood of SAFE_RETURNs is exactly what an
 * attack looks like once a shield enforces, so it must cost a bounded trickle of
 * records, not one per packet; the ring's own drop counter bounds it a second
 * time if even the trickle outruns the drain. The counter is atomic because two
 * TMM threads reach this path --- the same reason g_tp_seq is.
 */
#define LS_TP_SHIELD_BURST  8ull
#define LS_TP_SHIELD_EVERY  64ull
static _Atomic unsigned long long g_shield_ev_seen;

int
ls_tp_emit_shield(int slot, unsigned int gen, unsigned int mode,
                  unsigned int verdict, const void *ctx, unsigned long ctx_len)
{
    struct ls_tp_shield_ev ev;
    struct timespec        ts;
    unsigned long long     n;
    unsigned long          i, ncopy;

    ls_tp_seg_bootstrap();
    if (g_tp_seg == NULL)
        return -1;                       /* ring off --- the shipped default */

    n = atomic_fetch_add_explicit(&g_shield_ev_seen, 1, memory_order_relaxed) + 1;
    if (n > LS_TP_SHIELD_BURST && (n % LS_TP_SHIELD_EVERY) != 0)
        return -1;                       /* rate-limited; the drop is intentional */

    ev.mode    = mode;
    ev.gen     = gen;
    ev.verdict = verdict;
    ev.ctx_len = (unsigned int)ctx_len;
    ev.arg[0] = ev.arg[1] = ev.arg[2] = ev.arg[3] = ev.arg[4] = 0;
    /* Byte copy so a short ctx zero-fills its tail and a long one truncates ---
     * no <string.h> pulled into this bridge file for one memcpy. */
    ncopy = ctx_len < sizeof ev.arg ? ctx_len : sizeof ev.arg;
    for (i = 0; i < ncopy; i++)
        ((unsigned char *)ev.arg)[i] = ((const unsigned char *)ctx)[i];

    clock_gettime(CLOCK_REALTIME, &ts);
    return ls_tp_ring_publish(g_tp_seg, LS_TP_HOOK_SHIELD, LS_TP_SCHEMA_SHIELD,
                              (unsigned)slot,
                              atomic_fetch_add_explicit(&g_tp_seq, 1,
                                                        memory_order_relaxed),
                              (unsigned long long)ts.tv_sec * 1000000000ull
                                  + (unsigned long long)ts.tv_nsec,
                              &ev, (unsigned int)sizeof ev) == 0 ? 0 : -1;
}

ls_tp_ring.h.text:
/* ls_tp_ring.h --- the shared-memory segment the tracepoint publishes into.
 *
 * ls_ring.h is the ring: lock-free, bounded, 15 assertions, TSan clean. It has
 * never run inside TMM. This file is the missing half --- the segment that holds
 * the rings, who creates it, and which ring a given thread writes to.
 *
 * WHY SHARED MEMORY IS FORCED, NOT PREFERRED. TMM aliases malloc to a per-core
 * allocator whose spinlock is never initialised on a thread TMM did not create,
 * so a drain agent that allocates spins forever. Everything here is mmap.
 * Equally, the consumer must live in another process: a broker client linked
 * into TMM would put a socket, a reconnect and a stalled subscriber inside the
 * poll loop. TMM writes bytes and forgets; the agent maps them read-only and
 * publishes. It can crash without TMM noticing.
 *
 * ONE RING PER THREAD, BY CONSTRUCTION. ls_ring.h is single-producer --- that is
 * what lets it be lock-free, and it is a correctness precondition, not a
 * performance note. g_slots in ls_vm.c is a plain process-global despite
 * ls_prep.c describing "per-thread VM state", and the TMM process here runs
 * three threads. Whether more than one reaches the tracepoint is exactly the
 * kind of thing that has been assumed wrongly before, so each thread claims its
 * own ring by atomic index and writes only to that. The precondition then holds
 * whatever the thread model turns out to be.
 *
 * OFF UNLESS ASKED. Nothing here allocates, maps or executes unless LS_TP_RING
 * names a segment --- the same discipline as the loader socket. The shipped path
 * is a load of one pointer and a branch.
 */
#ifndef LS_TP_RING_H
#define LS_TP_RING_H

#include <fcntl.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>

#include "ls_tp.h"
#include "ls_ring.h"

#define LS_TP_SEG_MAGIC   0x4c53534547303031ull   /* "LSSEG001" */
/* Segment format version. ls_rec gained ts_ns, so a consumer built against
 * version 1 walks records at the wrong stride --- it must be REFUSED, not left to
 * decode plausible garbage. Checked in ls_tp_seg_open below. */
#define LS_TP_SEG_VERSION   2u
#define LS_TP_MAX_RINGS    16u
#define LS_TP_RING_BYTES   (64u * 1024u)          /* power of two --- ls_ring requires it */

/* Hook and schema identity live in ls_tp.h --- they are part of the
 * ls_tp_dispatch() contract, and the trampoline needs them without
 * dragging mmap and stdatomic in. */

/* Segment header, at offset 0. Rings follow at a fixed stride so a consumer can
 * find ring i without walking anything. */
struct ls_tp_seg {
    uint64_t magic;
    uint32_t version;
    uint32_t n_rings;
    uint32_t ring_stride;            /* bytes from one ring's start to the next */
    uint32_t ring_data_size;
    _Atomic uint32_t claimed;        /* how many threads have taken a ring      */
    uint32_t _pad;
};

#define LS_TP_STRIDE  ((uint32_t)sizeof(struct ls_ring) + LS_TP_RING_BYTES)
#define LS_TP_SEG_SZ  ((size_t)sizeof(struct ls_tp_seg) + \
                       (size_t)LS_TP_MAX_RINGS * LS_TP_STRIDE)

static inline struct ls_ring *
ls_tp_seg_ring(struct ls_tp_seg *s, uint32_t i)
{
    return (struct ls_ring *)((uint8_t *)s + sizeof(struct ls_tp_seg)
                              + (size_t)i * s->ring_stride);
}

/*
 * Create and map the segment. Idempotent and safe to call from every thread:
 * the loser of the race unmaps its own view and takes the winner's.
 *
 * Returns NULL when disabled or on any failure. EVERY failure path here is
 * non-fatal by design --- telemetry that can prevent TMM from starting is worse
 * than no telemetry.
 */
static inline struct ls_tp_seg *
ls_tp_seg_open(const char *path, int create)
{
    int fd, i;
    void *p;
    struct ls_tp_seg *s;

    if (path == NULL || *path == '\0')
        return NULL;

    fd = open(path, create ? (O_RDWR | O_CREAT) : O_RDWR, 0600);
    if (fd < 0)
        return NULL;

    if (create && ftruncate(fd, (off_t)LS_TP_SEG_SZ) != 0) {
        close(fd);
        return NULL;
    }

    p = mmap(NULL, LS_TP_SEG_SZ, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    close(fd);                        /* the mapping keeps the object alive */
    if (p == MAP_FAILED)
        return NULL;

    s = (struct ls_tp_seg *)p;
    if (!create) {
        if (s->magic != LS_TP_SEG_MAGIC || s->version != LS_TP_SEG_VERSION ||
            s->ring_stride != LS_TP_STRIDE) {
            munmap(p, LS_TP_SEG_SZ);
            return NULL;             /* wrong magic, wrong version, or wrong geometry */
        }
        return s;
    }

    /* Initialise every ring before publishing the magic, so a consumer that
     * opens mid-setup either sees no segment or sees a complete one. */
    s->version        = LS_TP_SEG_VERSION;
    s->n_rings        = LS_TP_MAX_RINGS;
    s->ring_stride    = LS_TP_STRIDE;
    s->ring_data_size = LS_TP_RING_BYTES;
    atomic_store_explicit(&s->claimed, 0, memory_order_relaxed);
    for (i = 0; i < (int)LS_TP_MAX_RINGS; i++)
        ls_ring_init(ls_tp_seg_ring(s, (uint32_t)i), LS_TP_RING_BYTES,
                     LS_RING_STREAM);

    /* STREAM, not RECORD, and the choice matters. A streaming analytic feed must
     * never have a record pulled out from under a mid-read consumer, and the
     * data plane must never wait on that consumer. Full therefore means drop the
     * NEW record and count it --- a counted gap, never a silent one, and never
     * backpressure into the poll loop. */

    __atomic_store_n(&s->magic, LS_TP_SEG_MAGIC, __ATOMIC_RELEASE);
    return s;
}

/*
 * The calling thread's own ring, claimed once and remembered.
 *
 * __thread rather than an index derived from a TMM thread id: the id is not
 * available in this include world, and a wrong index would silently give two
 * threads the same ring --- which does not crash, it corrupts records
 * occasionally, which is the worst way for this to be wrong.
 */
static inline struct ls_ring *
ls_tp_my_ring(struct ls_tp_seg *s)
{
    static __thread struct ls_ring *mine;
    static __thread int tried;
    uint32_t idx;

    if (mine != NULL || tried)
        return mine;
    tried = 1;                        /* claim at most once, even on failure */

    if (s == NULL)
        return NULL;

    idx = atomic_fetch_add_explicit(&s->claimed, 1, memory_order_relaxed);
    if (idx >= s->n_rings)
        return NULL;                  /* more threads than rings: this one is silent */

    mine = ls_tp_seg_ring(s, idx);
    return mine;
}

/*
 * Publish one record. Returns 1 if it landed, 0 if dropped or disabled.
 *
 * The entire cost on the hot path: a bounded memcpy and two ordered stores. No
 * allocation, no syscall, no lock --- which is the property that makes this
 * acceptable in a poll loop at all, and the one check_ring asserts by
 * construction rather than by inspection.
 */
static inline int
ls_tp_ring_publish(struct ls_tp_seg *seg, uint32_t hook_id, uint32_t schema_id,
                   uint32_t slot, uint64_t seq, uint64_t ts_ns,
                   const void *rec, uint32_t len)
{
    struct ls_ring *r = ls_tp_my_ring(seg);
    struct ls_rec h;

    if (r == NULL)
        return 0;

    h.hook_id   = hook_id;
    h.schema_id = schema_id;
    h.seq       = seq;
    h.slot      = slot;
    h.len       = len;
    h.ts_ns     = ts_ns;
    return ls_ring_emit(r, &h, rec, len);
}

#endif /* LS_TP_RING_H */

